                    adoptionGain += 10;
                    retentionGain -= 3;
                } else if (d.commStrategy === 'need_to_know') {
                    adoptionGain -= 5;
                    retentionGain += 2;
                }

                var digitalPct = d.incentiveDigital || 40;
                adoptionGain += (digitalPct - 40) * 0.3;
                var ebitdaImpact = -(digitalPct - 40) * 0.02;

                ds.employeeAdoption = Math.min(100, Math.max(0, ds.employeeAdoption + adoptionGain));
                ds.customerRetention = Math.max(0, Math.min(100, ds.customerRetention - 5 + retentionGain * 0.3));

                var spendingEffect = -(ds.budgetSpent / 2840) * 0.5;
                ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin + spendingEffect + ebitdaImpact);

                ds.rapidoShare = Math.min(50, ds.rapidoShare + 4);

                if (Math.random() < 0.5) {
                    eventMsg += window.mySimulation.t('event_whatsapp');
                    if (ds.selectedInits.indexOf('whatsapp') === -1) {
                        ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.3);
                    }
                }

            } else if (period === 2) {
                var adoptionGain2 = 0;
                var retentionGain2 = 0;
                ds.selectedInits.forEach(function(id) {
                    var init = self.INITIATIVES[id];
                    if (!init) return;
                    if (init.lead === 2) {
                        var remaining = 0.6;
                        Object.keys(init.dims).forEach(function(dim) {
                            var key = 'mat' + dim.charAt(0).toUpperCase() + dim.slice(1);
                            var current = ds[key] || 0;
                            var gain = init.dims[dim] * remaining;
                            var diminish = 1 - (current / 12);
                            ds[key] = Math.min(10, current + gain * diminish);
                        });
                        adoptionGain2 += init.adopt * remaining;
                        retentionGain2 += init.retain * remaining;
                    }
                });

                if (d.budgetAccel === 'invest_more') {
                    ds.budgetSpent += 400;
                    ds.budget -= 400;
                    ds.matTech = Math.min(10, ds.matTech + 0.5);
                    ds.matCx = Math.min(10, ds.matCx + 0.5);
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.2);
                } else if (d.budgetAccel === 'descope') {
                    ds.budget += 200;
                    ds.budgetSpent -= 200;
                    ds.matTech = Math.max(2, ds.matTech - 0.3);
                }

                if (d.attritionResponse === 'bonus') {
                    ds.budgetSpent += 280;
                    ds.budget -= 280;
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 8);
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.15);
                } else if (d.attritionResponse === 'communication') {
                    ds.salesReps -= 8;
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 5);
                    ds.matCulture = Math.min(10, ds.matCulture + 0.3);
                } else if (d.attritionResponse === 'accept') {
                    ds.salesReps -= 28;
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption - 5);
                    ds.customerRetention = Math.max(0, ds.customerRetention - 6);
                    ds.ebitdaMargin += 0.4;
                }

                if (d.bimboDecision === 'accept') {
                    ds.budget += 800;
                    ds.bimboAccepted = true;
                    ds.customerRetention = Math.min(100, ds.customerRetention + 3);
                    ds.matCx = Math.min(10, ds.matCx + 0.3);
                } else if (d.bimboDecision === 'negotiate') {
                    ds.budget += 400;
                    ds.customerRetention = Math.min(100, ds.customerRetention + 1);
                } else {
                    ds.matStrategy = Math.min(10, ds.matStrategy + 0.5);
                }

                ds.employeeAdoption = Math.min(100, Math.max(0, ds.employeeAdoption + adoptionGain2));
                ds.customerRetention = Math.max(0, Math.min(100, ds.customerRetention + retentionGain2 * 0.2));

                var opsGain = (ds.matOps - 4.1) * 0.15;
                ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin + opsGain);

                eventMsg += window.mySimulation.t('event_sunat');
                if (ds.selectedInits.indexOf('erp_api') === -1) {
                    ds.budgetSpent += 250;
                    ds.budget -= 250;
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.3);
                    eventMsg += '<br>' + window.mySimulation.t('event_sunat_penalty');
                }

                if (Math.random() < 0.25) {
                    eventMsg += '<br>' + window.mySimulation.t('event_blackout');
                    if (ds.selectedInits.indexOf('route_ai') !== -1) {
                        ds.customerRetention = Math.max(0, ds.customerRetention - 1);
                    } else {
                        ds.customerRetention = Math.max(0, ds.customerRetention - 4);
                    }
                }

                var rapidoGrowth = ds.selectedInits.indexOf('app') !== -1 ? 1.5 : 3.5;
                ds.rapidoShare = Math.min(50, ds.rapidoShare + rapidoGrowth);

            } else if (period === 3) {
                ds.endgame = d.endgame;

                if (d.endgame === 'distributor4') {
                    ds.matOps = Math.min(10, ds.matOps + 1.0);
                    ds.matTech = Math.min(10, ds.matTech + 0.5);
                    ds.ebitdaMargin += 0.8;
                    ds.customerRetention = Math.min(100, ds.customerRetention + 3);
                    if (ds.matOps >= 7) {
                        ds.ebitdaMargin += 0.5;
                        ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 5);
                    }
                } else if (d.endgame === 'platform') {
                    ds.matCx = Math.min(10, ds.matCx + 1.5);
                    ds.matStrategy = Math.min(10, ds.matStrategy + 1.0);
                    ds.ebitdaMargin -= 0.5;
                    if (ds.matCx >= 6.5 && ds.matTech >= 6.5) {
                        ds.ebitdaMargin += 1.5;
                        ds.rapidoShare = Math.max(0, ds.rapidoShare - 5);
                    }
                    if (ds.bimboAccepted) {
                        ds.matStrategy = Math.max(2, ds.matStrategy - 0.8);
                    }
                } else if (d.endgame === 'logistics') {
                    ds.matOps = Math.min(10, ds.matOps + 1.5);
                    ds.ebitdaMargin += 0.3;
                    ds.customerRetention = Math.max(0, ds.customerRetention - 8);
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption - 10);
                    if (ds.matOps >= 7) {
                        ds.ebitdaMargin += 1.0;
                    }
                }

                if (Math.random() < 0.7) {
                    eventMsg += window.mySimulation.t('event_series_b');
                    ds.rapidoShare = Math.min(50, ds.rapidoShare + 3);
                    if (d.endgame === 'platform') {
                        ds.rapidoShare = Math.min(50, ds.rapidoShare + 2);
                    }
                }

                if (Math.random() < 0.35) {
                    if (eventMsg) eventMsg += '<br>';
                    eventMsg += window.mySimulation.t('event_disintermediation');
                    ds.customerRetention = Math.max(0, ds.customerRetention - 3);
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.4);
                }

                ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 3);
                var cxEffect = (ds.matCx - 2.8) * 0.8;
                ds.customerRetention = Math.min(100, ds.customerRetention + cxEffect * 0.3);
            }

            ds.dtScore = Math.round(((ds.matCx + ds.matOps + ds.matStrategy + ds.matCulture + ds.matTech) / 5) * 10) / 10;
            ds.ebitdaMargin = Math.round(Math.max(0, Math.min(15, ds.ebitdaMargin)) * 10) / 10;
            ds.customerRetention = Math.round(Math.max(0, Math.min(100, ds.customerRetention)) * 10) / 10;
            ds.employeeAdoption = Math.round(Math.max(0, Math.min(100, ds.employeeAdoption)) * 10) / 10;
            ds.rapidoShare = Math.round(Math.max(0, Math.min(50, ds.rapidoShare)) * 10) / 10;

            ds.dtScoreHistory.push(ds.dtScore);
            ds.ebitdaHistory.push(ds.ebitdaMargin);
            ds.retentionHistory.push(ds.customerRetention);
            ds.adoptionHistory.push(ds.employeeAdoption);
            ds.rapidoHistory.push(ds.rapidoShare);
            ds.eventLog = eventMsg;

            if (eventMsg) {
                var alertEl = document.getElementById('eventAlert');
                var textEl = document.getElementById('eventText');
                if (alertEl) alertEl.style.display = 'block';
                if (textEl) textEl.innerHTML = eventMsg;
            }

            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod, domainState: ds });
            }, 500);

            // same weighted total as getPerformanceSummary (max 1000), scaled by 10 to a 0-100 platform score
            var rapidoGainX = ds.rapidoShare - 26;
            var dtPointsX = Math.min(300, (ds.dtScore / 10) * 300);
            var retPointsX = Math.min(250, (ds.customerRetention / 100) * 250);
            var ebitdaPointsX = Math.min(200, (ds.ebitdaMargin / 10) * 200);
            var adoptPointsX = Math.min(150, (ds.employeeAdoption / 100) * 150);
            var rapidoPointsX = rapidoGainX <= 15 ? 100 : Math.max(0, 100 - (rapidoGainX - 15) * 10);
            var totalScoreX = dtPointsX + retPointsX + ebitdaPointsX + adoptPointsX + rapidoPointsX;
            var overallScoreX = Math.max(0, Math.min(100, Math.round(totalScoreX / 10)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScoreX });

            return {
                period: period,
                dtScore: ds.dtScore,
                customerRetention: ds.customerRetention,
                ebitdaMargin: ds.ebitdaMargin,
                employeeAdoption: ds.employeeAdoption,
                rapidoShare: ds.rapidoShare,
                budgetRemaining: ds.budget,
                events: eventMsg
            };
        }

