        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var dtScore = r.dtScore || 0;
            var retention = r.customerRetention || 0;
            var ebitda = r.ebitdaMargin || 0;
            var adoption = r.employeeAdoption || 0;
            var rapidoGain = (r.rapidoShare || 26) - 26;

            var dtPoints = Math.min(300, (dtScore / 10) * 300);
            var retPoints = Math.min(250, (retention / 100) * 250);
            var ebitdaPoints = Math.min(200, (ebitda / 10) * 200);
            var adoptPoints = Math.min(150, (adoption / 100) * 150);
            var rapidoPoints = rapidoGain <= 15 ? 100 : Math.max(0, 100 - (rapidoGain - 15) * 10);
            var totalScore = Math.round(dtPoints + retPoints + ebitdaPoints + adoptPoints + rapidoPoints);

            var t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var performance = t('perf_needs');
            if (totalScore >= 700) performance = t('perf_excellent');
            else if (totalScore >= 550) performance = t('perf_good');
            else if (totalScore >= 400) performance = t('perf_developing');

            var insights = [];
            if (dtScore >= 7) {
                insights.push(t('insight_dt_strong'));
            } else {
                insights.push(t('insight_dt_weak'));
            }
            if (retention >= 85) {
                insights.push(t('insight_ret_met'));
            } else {
                insights.push(t('insight_ret_low'));
            }
            if (adoption < 70) {
                insights.push(t('insight_adopt_low'));
            }
            if (rapidoGain > 15) {
                insights.push(t('insight_rapido'));
            }

            return {
                totalScore: totalScore,
                dtScore: dtScore,
                customerRetention: retention,
                ebitdaMargin: ebitda,
                employeeAdoption: adoption,
                rapidoShareGain: rapidoGain,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.employeeAdoption < 30) return window.mySimulation.t('hint_low_adoption');
            if (results.customerRetention < 80) return window.mySimulation.t('hint_low_retention');
            if (results.ebitdaMargin < 3) return window.mySimulation.t('hint_low_ebitda');
            if (results.rapidoShare > 38) return window.mySimulation.t('hint_rapido_growing');
            return null;
        }

